function deepClone(obj) {
  // 1. Base case: Primitive values or null
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  // 2. Handle Arrays
  if (Array.isArray(obj)) {
    const copyArr = [];
    for (let i = 0; i < obj.length; i++) {
      copyArr[i] = deepClone(obj[i]); // Recursion!
    }
    return copyArr;
  }

  // 3. Handle Objects
  const copyObj = {};
  for (let key in obj) {
    if (obj.hasOwnProperty(key)) {
      copyObj[key] = deepClone(obj[key]); // Recursion!
    }
  }
  return copyObj;
}

const orig = { a: 1, b: { c: 2 } };
const clone = deepClone(orig);
clone.b.c = 99;
console.log(orig.b.c); // 2 (Original is safe!)
